using System.ComponentModel.DataAnnotations;using System.Text.Json;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.AspNetCore.Mvc.Rendering;using Microsoft.EntityFrameworkCore;using NoryMusicLMS_VS.Data;using NoryMusicLMS_VS.Models;using NoryMusicLMS_VS.Services;
namespace NoryMusicLMS_VS.Areas.Admin.Pages.QuizQuestions;
[Authorize(Roles="Admin")] public class EditModel:PageModel{private readonly ApplicationDbContext _db;private readonly ImageStorageService _images;private readonly AudioStorageService _audio;public EditModel(ApplicationDbContext db,ImageStorageService images,AudioStorageService audio){_db=db;_images=images;_audio=audio;}[BindProperty]public InputModel Input{get;set;}=new();public int QuestionId{get;private set;}public string? CurrentImageUrl{get;private set;}public string? CurrentAudioUrl{get;private set;}public class InputModel{[Required]public int QuizId{get;set;}[Required,StringLength(500)]public string QuestionText{get;set;}="";public QuestionType Type{get;set;}public int Points{get;set;}=1;public int OrderIndex{get;set;}=1;public string? Option1{get;set;}public string? Option2{get;set;}public string? Option3{get;set;}public string? Option4{get;set;}public int CorrectOptionNumber{get;set;}=1;public string? CorrectAnswerText{get;set;}public string? AudioUrl{get;set;}public string? ToneSequence{get;set;}public IFormFile? Image{get;set;}public bool RemoveImage{get;set;}public IFormFile? Audio{get;set;}public bool RemoveAudio{get;set;}}
public async Task<IActionResult> OnGetAsync(int id){var q=await _db.QuizQuestions.Include(x=>x.Quiz).FirstOrDefaultAsync(x=>x.Id==id);if(q is null)return NotFound();Set(q);await LoadQuizzesAsync();return Page();}public async Task<IActionResult> OnPostAsync(int id){var q=await _db.QuizQuestions.Include(x=>x.Quiz).FirstOrDefaultAsync(x=>x.Id==id);if(q is null)return NotFound();QuestionId=id;CurrentImageUrl=q.ImageUrl;CurrentAudioUrl=q.AudioUrl;var quiz=await _db.Quizzes.Include(x=>x.Lesson).ThenInclude(l=>l.Course).FirstOrDefaultAsync(x=>x.Id==Input.QuizId&&x.Lesson.Course.IsActive);if(quiz is null)ModelState.AddModelError("Input.QuizId","Select a quiz from an active course.");if(Input.Points<1)ModelState.AddModelError("Input.Points","Points must be at least 1.");var opts=Input.Type==QuestionType.TrueFalse?["True","False"]:new[]{Input.Option1,Input.Option2,Input.Option3,Input.Option4}.Where(x=>!string.IsNullOrWhiteSpace(x)).Select(x=>x!.Trim()).ToList();if(Input.Type is QuestionType.MultipleChoice or QuestionType.TrueFalse){if(opts.Count<2)ModelState.AddModelError(string.Empty,"Provide at least two options.");if(Input.CorrectOptionNumber<1||Input.CorrectOptionNumber>opts.Count)ModelState.AddModelError("Input.CorrectOptionNumber","Choose a valid correct option.");}else if(string.IsNullOrWhiteSpace(Input.CorrectAnswerText))ModelState.AddModelError("Input.CorrectAnswerText","Enter the expected answer.");if(Input.Type==QuestionType.AudioIdentification&&string.IsNullOrWhiteSpace(Input.AudioUrl)&&Input.Audio is not { Length: > 0 }&&string.IsNullOrWhiteSpace(Input.ToneSequence))ModelState.AddModelError(string.Empty,"Add an audio URL or tone sequence.");if(ImageStorageService.Validate(Input.Image) is{ }e)ModelState.AddModelError("Input.Image",e);if(AudioStorageService.Validate(Input.Audio) is{ }ae)ModelState.AddModelError("Input.Audio",ae);if(!ModelState.IsValid){await LoadQuizzesAsync();return Page();}q.QuizId=Input.QuizId;q.QuestionText=Input.QuestionText.Trim();q.Type=Input.Type;q.Points=Input.Points;q.OrderIndex=Input.OrderIndex;q.OptionsJson=Input.Type is QuestionType.MultipleChoice or QuestionType.TrueFalse?JsonSerializer.Serialize(opts):null;q.CorrectAnswerIndex=Input.Type is QuestionType.MultipleChoice or QuestionType.TrueFalse?Input.CorrectOptionNumber-1:null;q.CorrectAnswerText=Input.CorrectAnswerText?.Trim();q.AudioUrl=await _audio.ApplyAsync(q.AudioUrl,Input.Audio,Input.RemoveAudio,null);q.ToneSequence=Input.ToneSequence?.Trim();q.ImageUrl=await _images.ApplyAsync(q.ImageUrl,Input.Image,Input.RemoveImage,null);await _db.SaveChangesAsync();return RedirectToPage("./Index");}private void Set(QuizQuestion q){QuestionId=q.Id;CurrentImageUrl=q.ImageUrl;CurrentAudioUrl=q.AudioUrl;var opts=new List<string>();if(!string.IsNullOrWhiteSpace(q.OptionsJson))try{opts=JsonSerializer.Deserialize<List<string>>(q.OptionsJson)??[];}catch{}Input=new(){QuizId=q.QuizId,QuestionText=q.QuestionText,Type=q.Type,Points=q.Points,OrderIndex=q.OrderIndex,Option1=opts.ElementAtOrDefault(0),Option2=opts.ElementAtOrDefault(1),Option3=opts.ElementAtOrDefault(2),Option4=opts.ElementAtOrDefault(3),CorrectOptionNumber=(q.CorrectAnswerIndex??0)+1,CorrectAnswerText=q.CorrectAnswerText,AudioUrl=q.AudioUrl,ToneSequence=q.ToneSequence};}private async Task LoadQuizzesAsync()=>ViewData["QuizId"]=new SelectList(await _db.Quizzes.Include(q=>q.Lesson).ThenInclude(l=>l.Course).Where(q=>q.Lesson.Course.IsActive).OrderBy(q=>q.Lesson.Course.Title).ThenBy(q=>q.Lesson.Title).ThenBy(q=>q.Title).Select(q=>new{q.Id,Label=q.Lesson.Course.Title+" — "+q.Lesson.Title+" — "+q.Title}).ToListAsync(),"Id","Label",Input.QuizId);}
